#include "model_skinning_geometry.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("MDL required");std::ifstream f(argv[1],std::ios::binary);if(!f)throw std::runtime_error("MDL missing");std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(f)),{});auto bones=readGeometrySkeletonCandidate(bytes);size_t count=0;for(size_t n=0;n<bones.size();++n)if(bones[n].procedure==5){auto&bone=bones[n];if(!bone.hasJiggleParameters)throw std::runtime_error("procedure parameters lost");std::cout<<"bone="<<n<<" flags="<<bone.jiggleParameters.flags<<" length="<<bone.jiggleParameters.values[0]<<"\n";++count;}if(count!=17)throw std::runtime_error("fixture coverage");size_t rejected=0;for(int mode=0;mode<4;++mode){std::vector<uint8_t>record(120);uint32_t flags=49;float length=20;std::memcpy(record.data(),&flags,4);std::memcpy(record.data()+4,&length,4);if(mode==0)record.resize(119);if(mode==1){flags=128;std::memcpy(record.data(),&flags,4);}if(mode==2){uint32_t nan=0x7fc00000;std::memcpy(record.data()+8,&nan,4);}if(mode==3){length=0;std::memcpy(record.data()+4,&length,4);}bool failed=false;try{readJiggleParametersCandidate(record,0);}catch(std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("malformed jiggle record accepted");++rejected;}std::cout<<"real jiggle records retained="<<count<<" malformed_rejected="<<rejected<<" simulation=unfinished\n";return 0;}catch(std::exception&e){std::cerr<<e.what();return 1;}}
